/**
 * My Talking App - With Splash Screen Video
 */

import React, { useState, useRef, useEffect } from 'react';
import {
  StyleSheet,
  View,
  StatusBar,
  Text,
  NativeModules,
  NativeEventEmitter,
  PermissionsAndroid,
} from 'react-native';
import { WebView } from 'react-native-webview';
import Video from 'react-native-video';
import Tts from 'react-native-tts';

const { SpeechModule } = NativeModules;

// Background image will be injected here
const BG_IMAGE_DATA_URI = 'data:image/png;base64,';

const robotHTML = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
    <style>
        * { margin: 0; padding: 0; }
        body { 
            overflow: hidden; 
            touch-action: none;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
        }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="importmap">
    {
        "imports": {
            "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
            "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
        }
    }
    </script>
    
    <script type="module">
        import * as THREE from 'three';
        import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        let camera, scene, renderer, model, mixer, clock;
        let actions = {};
        let activeAction;
        let face;
        let mouthInterval = null;
        let backgroundTexture = null;
        let floorGroup = null;

        window.addEventListener('message', function(event) {
            try {
                const data = JSON.parse(event.data);
                if (data.type === 'startTalk') playTalkAnimation();
                else if (data.type === 'stopTalk') playIdleAnimation();
                else if (data.type === 'listen') playListenAnimation();
            } catch (e) {}
        });

        function playTalkAnimation() {
            if (actions['Wave']) fadeToAction('Wave', 0.3);
            animateMouth(true);
        }

        function playIdleAnimation() {
            fadeToAction('Idle', 0.5);
            animateMouth(false);
        }

        function playListenAnimation() {
            if (actions['ThumbsUp']) fadeToAction('ThumbsUp', 0.3);
        }

        function animateMouth(start) {
            if (mouthInterval) clearInterval(mouthInterval);
            mouthInterval = null;
            
            if (start && face && face.morphTargetInfluences) {
                mouthInterval = setInterval(() => {
                    if (face && face.morphTargetInfluences) {
                        const mouthOpen = Math.random() * 0.6;
                        for (let i = 0; i < face.morphTargetInfluences.length; i++) {
                            face.morphTargetInfluences[i] = mouthOpen;
                        }
                    }
                }, 100);
            } else if (face && face.morphTargetInfluences) {
                for (let i = 0; i < face.morphTargetInfluences.length; i++) {
                    face.morphTargetInfluences[i] = 0;
                }
            }
        }

        function createDefaultFloor() {
            const floorSize = 20;
            const floorGeometry = new THREE.PlaneGeometry(floorSize, floorSize, 20, 20);
            
            const floorCanvas = document.createElement('canvas');
            const ts = 64;
            floorCanvas.width = ts * 8;
            floorCanvas.height = ts * 8;
            const floorCtx = floorCanvas.getContext('2d');
            
            const tileDark = 'rgba(12, 40, 75, 0.95)';
            const tileLight = 'rgba(18, 28, 52, 0.92)';
            const accent = 'rgba(0, 217, 255, 0.2)';
            for (let row = 0; row < 8; row++) {
                for (let col = 0; col < 8; col++) {
                    floorCtx.fillStyle = (row + col) % 2 === 0 ? tileLight : tileDark;
                    floorCtx.fillRect(col * ts, row * ts, ts, ts);
                    floorCtx.strokeStyle = accent;
                    floorCtx.lineWidth = 1;
                    floorCtx.strokeRect(col * ts, row * ts, ts, ts);
                }
            }
            const centerX = floorCanvas.width / 2, centerY = floorCanvas.height / 2;
            const vignette = floorCtx.createRadialGradient(centerX, centerY, 0, centerX, centerY, centerX);
            vignette.addColorStop(0.65, 'rgba(0,0,0,0)');
            vignette.addColorStop(1, 'rgba(0,0,0,0.25)');
            floorCtx.fillStyle = vignette;
            floorCtx.fillRect(0, 0, floorCanvas.width, floorCanvas.height);
            
            const floorTexture = new THREE.CanvasTexture(floorCanvas);
            floorTexture.wrapS = THREE.RepeatWrapping;
            floorTexture.wrapT = THREE.RepeatWrapping;
            floorTexture.repeat.set(2, 2);
            
            const ground = new THREE.Mesh(
                floorGeometry,
                new THREE.MeshStandardMaterial({ 
                    map: floorTexture,
                    color: 0xffffff,
                    metalness: 0.12,
                    roughness: 0.88,
                    transparent: false,
                    opacity: 1,
                    emissive: 0x001a33,
                    emissiveIntensity: 0.06
                })
            );
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            if (floorGroup) {
                while (floorGroup.children.length) floorGroup.remove(floorGroup.children[0]);
                floorGroup.add(ground);
            } else { scene.add(ground); }

            const grid = new THREE.GridHelper(floorSize, 20, 0x00d9ff, 0x00d9ff);
            grid.material.opacity = 0.18;
            grid.material.transparent = true;
            if (floorGroup) floorGroup.add(grid); else scene.add(grid);
        }

        function createFloorFromBackground(bgTexture) {
            const floorSize = 20;
            const floorGeometry = new THREE.PlaneGeometry(floorSize, floorSize, 20, 20);
            
            // Wait for image to load
            const img = bgTexture.image;
            if (!img || !img.complete) {
                img.onload = function() {
                    createFloorFromBackground(bgTexture);
                };
                return;
            }
            
            // Create canvas to sample colors from background
            const sampleCanvas = document.createElement('canvas');
            sampleCanvas.width = img.width || 512;
            sampleCanvas.height = img.height || 512;
            const sampleCtx = sampleCanvas.getContext('2d');
            sampleCtx.drawImage(img, 0, 0);
            
            // Sample colors from bottom part of background (where floor would be)
            const startY = Math.floor(sampleCanvas.height * 0.7);
            const height = Math.floor(sampleCanvas.height * 0.3);
            const imgData = sampleCtx.getImageData(0, startY, sampleCanvas.width, height);
            const pixels = imgData.data;
            
            // Calculate average colors from bottom section
            let r = 0, g = 0, b = 0, count = 0;
            for (let i = 0; i < pixels.length; i += 16) { // Sample every 4th pixel
                r += pixels[i];
                g += pixels[i + 1];
                b += pixels[i + 2];
                count++;
            }
            r = Math.floor(r / count);
            g = Math.floor(g / count);
            b = Math.floor(b / count);
            
            // Create floor texture – tile pattern from sampled colors
            const floorCanvas = document.createElement('canvas');
            const ts = 64;
            floorCanvas.width = ts * 8;
            floorCanvas.height = ts * 8;
            const floorCtx = floorCanvas.getContext('2d');
            const r1 = Math.floor(r * 0.85), g1 = Math.floor(g * 0.85), b1 = Math.floor(b * 0.85);
            const r2 = Math.floor(r * 0.6), g2 = Math.floor(g * 0.6), b2 = Math.floor(b * 0.6);
            const tileLight = 'rgba(' + r1 + ',' + g1 + ',' + b1 + ',0.94)';
            const tileDark = 'rgba(' + r2 + ',' + g2 + ',' + b2 + ',0.92)';
            const accent = 'rgba(' + r + ',' + g + ',' + b + ',0.22)';
            for (let row = 0; row < 8; row++) {
                for (let col = 0; col < 8; col++) {
                    floorCtx.fillStyle = (row + col) % 2 === 0 ? tileLight : tileDark;
                    floorCtx.fillRect(col * ts, row * ts, ts, ts);
                    floorCtx.strokeStyle = accent;
                    floorCtx.lineWidth = 1;
                    floorCtx.strokeRect(col * ts, row * ts, ts, ts);
                }
            }
            const centerX = floorCanvas.width / 2, centerY = floorCanvas.height / 2;
            const vignette = floorCtx.createRadialGradient(centerX, centerY, 0, centerX, centerY, centerX);
            vignette.addColorStop(0.65, 'rgba(0,0,0,0)');
            vignette.addColorStop(1, 'rgba(0,0,0,0.2)');
            floorCtx.fillStyle = vignette;
            floorCtx.fillRect(0, 0, floorCanvas.width, floorCanvas.height);
            
            const floorTexture = new THREE.CanvasTexture(floorCanvas);
            floorTexture.wrapS = THREE.RepeatWrapping;
            floorTexture.wrapT = THREE.RepeatWrapping;
            floorTexture.repeat.set(2, 2);
            
            const ground = new THREE.Mesh(
                floorGeometry,
                new THREE.MeshStandardMaterial({ 
                    map: floorTexture,
                    color: 0xffffff,
                    metalness: 0.12,
                    roughness: 0.88,
                    transparent: false,
                    opacity: 1,
                    emissive: (r << 16) | (g << 8) | b,
                    emissiveIntensity: 0.05
                })
            );
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            if (floorGroup) {
                while (floorGroup.children.length) floorGroup.remove(floorGroup.children[0]);
                floorGroup.add(ground);
            } else { scene.add(ground); }

            const gridColor = (r << 16) | (g << 8) | b;
            const grid = new THREE.GridHelper(floorSize, 20, gridColor, gridColor);
            grid.material.opacity = 0.16;
            grid.material.transparent = true;
            if (floorGroup) floorGroup.add(grid); else scene.add(grid);
            
            // Subtle ring using sampled colors
            const ringGeometry = new THREE.RingGeometry(14, 15, 64);
            const ringMaterial = new THREE.MeshStandardMaterial({
                color: 'rgb(' + r + ', ' + g + ', ' + b + ')',
                emissive: 'rgb(' + r + ', ' + g + ', ' + b + ')',
                emissiveIntensity: 0.1,
                transparent: true,
                opacity: 0.25,
                side: THREE.DoubleSide
            });
            const ring = new THREE.Mesh(ringGeometry, ringMaterial);
            ring.rotation.x = -Math.PI / 2;
            if (floorGroup) floorGroup.add(ring); else scene.add(ring);
        }

        function init() {
            scene = new THREE.Scene();
            floorGroup = new THREE.Group();
            floorGroup.position.y = -0.35;
            scene.add(floorGroup);
            const loader = new THREE.TextureLoader();
            const bgImage = '${BG_IMAGE_DATA_URI}';
            if (bgImage && bgImage !== 'BG_IMAGE_PLACEHOLDER') {
            loader.load(bgImage, function(texture) {
                backgroundTexture = texture;
                // Set as equirectangular panorama for 360-degree view
                texture.mapping = THREE.EquirectangularReflectionMapping;
                texture.flipY = true; // Flip vertically to fix upside down image
                scene.background = texture;
                scene.environment = texture; // Also use for reflections
                
                console.log('Background image loaded as 360 panorama');
                
                // Create floor texture from background image colors
                createFloorFromBackground(texture);
            }, undefined, function(error) {
                console.error('Background image load error:', error);
                // Fallback to gradient
                const canvas = document.createElement('canvas');
                canvas.width = 2; canvas.height = 512;
                const ctx = canvas.getContext('2d');
                const gradient = ctx.createLinearGradient(0, 0, 0, 512);
                gradient.addColorStop(0, '#1a1a2e');
                gradient.addColorStop(0.5, '#16213e');
                gradient.addColorStop(1, '#0f3460');
                ctx.fillStyle = gradient;
                ctx.fillRect(0, 0, 2, 512);
                scene.background = new THREE.CanvasTexture(canvas);
                // Create default floor
                createDefaultFloor();
            });
            } else {
                // No background image, use gradient
                const canvas = document.createElement('canvas');
                canvas.width = 2; canvas.height = 512;
                const ctx = canvas.getContext('2d');
                const gradient = ctx.createLinearGradient(0, 0, 0, 512);
                gradient.addColorStop(0, '#1a1a2e');
                gradient.addColorStop(0.5, '#16213e');
                gradient.addColorStop(1, '#0f3460');
                ctx.fillStyle = gradient;
                ctx.fillRect(0, 0, 2, 512);
                scene.background = new THREE.CanvasTexture(canvas);
                // Create default floor
                createDefaultFloor();
            }
            // Reduced fog for better 360 panorama visibility
            scene.fog = new THREE.Fog(0x16213e, 30, 100);

            clock = new THREE.Clock();
            camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.25, 100);
            camera.position.set(0, 2.5, 12);
            camera.lookAt(0, 1, 0);

            scene.add(new THREE.HemisphereLight(0x00d9ff, 0x444444, 2));
            const dirLight = new THREE.DirectionalLight(0xffffff, 3);
            dirLight.position.set(5, 10, 7.5);
            scene.add(dirLight);

            // Floor will be created from background image colors

            new GLTFLoader().load(
                'https://threejs.org/examples/models/gltf/RobotExpressive/RobotExpressive.glb',
                function (gltf) {
                    model = gltf.scene;
                    model.scale.setScalar(0.72);
                    model.position.set(0, 0, -1.2);
                    model.traverse((child) => {
                        if (child.isMesh) child.castShadow = true;
                        if (child.name === 'Head_4') face = child;
                    });
                    scene.add(model);

                    mixer = new THREE.AnimationMixer(model);
                    gltf.animations.forEach(clip => {
                        const action = mixer.clipAction(clip);
                        actions[clip.name] = action;
                        if (['Jump', 'Yes', 'No', 'Wave', 'Punch', 'ThumbsUp', 'Death'].includes(clip.name)) {
                            action.clampWhenFinished = true;
                            action.loop = THREE.LoopOnce;
                        }
                    });

                    activeAction = actions['Idle'];
                    if (activeAction) activeAction.play();
                    if (typeof controls !== 'undefined') controls.target.set(0, 0, -1.2);
                    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'ready' }));
                }
            );

            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setAnimationLoop(() => {
                if (mixer) mixer.update(clock.getDelta());
                renderer.render(scene, camera);
            });
            document.body.appendChild(renderer.domElement);

            const controls = new OrbitControls(camera, renderer.domElement);
            controls.target.set(0, 0, 0);
            controls.enableDamping = true;
            controls.dampingFactor = 0.12;
            controls.enableZoom = false;
            controls.minDistance = 10;
            controls.maxDistance = 25;
            // Sirf 360 horizontal ghoomna (niche), up-down lock – bas horizontal rotate
            const polarAngle = Math.PI / 2.15;
            controls.minPolarAngle = polarAngle;
            controls.maxPolarAngle = polarAngle;
            controls.enablePan = false;
            controls.update();
            
            // Equirectangular mapping automatically handles 360-degree background rotation

            window.addEventListener('resize', () => {
                camera.aspect = window.innerWidth / window.innerHeight;
                camera.updateProjectionMatrix();
                renderer.setSize(window.innerWidth, window.innerHeight);
            });
        }

        function fadeToAction(name, duration) {
            const prev = activeAction;
            activeAction = actions[name];
            if (!activeAction) return;
            if (prev && prev !== activeAction) prev.fadeOut(duration);
            activeAction.reset().setEffectiveTimeScale(1).setEffectiveWeight(1).fadeIn(duration).play();
        }

        init();
    </script>
</body>
</html>
`;

let globalLoopTimer: any = null;

function App(): React.JSX.Element {
  const [showSplash, setShowSplash] = useState(true);
  const [status, setStatus] = useState('Loading');
  const webViewRef = useRef<WebView>(null);
  const robotReadyRef = useRef(false);

  const sendToWebView = (msg: object) => {
    webViewRef.current?.postMessage(JSON.stringify(msg));
  };

  const requestMicPermission = async (): Promise<boolean> => {
    try {
      const granted = await PermissionsAndroid.request(
        PermissionsAndroid.PERMISSIONS.RECORD_AUDIO,
        { title: 'Mic Permission', message: 'Robot ko sunne ke liye', buttonPositive: 'OK' }
      );
      return granted === PermissionsAndroid.RESULTS.GRANTED;
    } catch (e) {
      return false;
    }
  };

  const doListen = async () => {
    if (!SpeechModule || !robotReadyRef.current) {
      scheduleNext(800);
      return;
    }

    const hasPermission = await requestMicPermission();
    if (!hasPermission) {
      scheduleNext(1500);
      return;
    }

    setStatus('Listening');
    sendToWebView({ type: 'listen' });

    try {
      const result = await SpeechModule.startSpeechToText('hi-IN');
      sendToWebView({ type: 'stopTalk' });

      if (result && result.trim()) {
        doSpeak(result);
      } else {
        doListen();
      }
    } catch (error: any) {
      sendToWebView({ type: 'stopTalk' });
      doListen();
    }
  };

  const doSpeak = (text: string) => {
    setStatus('Speaking');
    sendToWebView({ type: 'startTalk' });
    Tts.stop();
    const isHindi = /[\u0900-\u097F]/.test(text);
    Tts.setDefaultLanguage(isHindi ? 'hi-IN' : 'en-US').catch(() => {});
    Tts.speak(text);
  };

  const scheduleNext = (delay: number) => {
    if (globalLoopTimer) clearTimeout(globalLoopTimer);
    globalLoopTimer = setTimeout(() => {
      if (robotReadyRef.current) {
        doListen();
      }
    }, delay);
  };

  useEffect(() => {
    Tts.getInitStatus().then(() => {
      Tts.setDefaultRate(0.5);
      Tts.setDefaultPitch(1.0);
    }).catch(() => {});

    const onFinish = () => {
      sendToWebView({ type: 'stopTalk' });
      setStatus('Rest');
      scheduleNext(700);
    };

    Tts.addEventListener('tts-finish', onFinish);
    Tts.addEventListener('tts-cancel', onFinish);

    return () => {
      robotReadyRef.current = false;
      if (globalLoopTimer) clearTimeout(globalLoopTimer);
      Tts.removeAllListeners('tts-finish');
      Tts.removeAllListeners('tts-cancel');
      SpeechModule?.destroy();
    };
  }, []);

  const onRobotReady = () => {
    robotReadyRef.current = true;
    setStatus('Rest');
    globalLoopTimer = setTimeout(() => {
      doListen();
    }, 900);
  };

  const onSplashEnd = () => {
    setShowSplash(false);
  };

  // Splash Screen
  if (showSplash) {
  return (
      <View style={styles.splashContainer}>
        <StatusBar hidden={true} />
        <Video
          source={require('./android/app/src/main/res/raw/splash.mp4')}
          style={styles.splashVideo}
          resizeMode="cover"
          onEnd={onSplashEnd}
          repeat={false}
          muted={false}
        />
      </View>
  );
}

  // Main App
  return (
    <View style={styles.container}>
      <StatusBar hidden={true} />
      
      <WebView
        ref={webViewRef}
        source={{ html: robotHTML }}
        style={styles.webview}
        javaScriptEnabled={true}
        domStorageEnabled={true}
        mixedContentMode="always"
        originWhitelist={['*']}
        scrollEnabled={false}
        onMessage={(e) => {
          try {
            const data = JSON.parse(e.nativeEvent.data);
            if (data.type === 'ready') {
              onRobotReady();
            }
          } catch {}
        }}
      />

      <View style={styles.statusBadge}>
        <Text style={styles.statusText}>{status}</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  splashContainer: {
    flex: 1,
    backgroundColor: '#000',
  },
  splashVideo: {
    flex: 1,
    width: '100%',
    height: '100%',
  },
  container: { 
    flex: 1, 
    backgroundColor: '#1a1a2e' 
  },
  webview: { 
    flex: 1 
  },
  statusBadge: {
    position: 'absolute',
    top: 20,
    alignSelf: 'center',
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    paddingHorizontal: 15,
    paddingVertical: 6,
    borderRadius: 15,
  },
  statusText: {
    color: '#00d9ff',
    fontSize: 12,
    fontWeight: '600',
  },
});

export default App;
